<?php
declare(strict_types=1);
namespace FMonitor2\RuntimeRestore;
final class ProductionStandRestoreDriver implements StandRestoreDriver
{
 public function preflight(StandRestoreAuthorization$a):string{return$this->matches($a,$this->observe($a))?'VERIFIED':'TARGET_INVALID';}
 public function restore(StandRestoreAuthorization$a,array$p):array{try{$password=trim(StandBackupFilesystem::regularBytes($a->value('credential_files')['database']));$c=$this->compose($a);$s=$a->value('services');$env=['MYSQL_PWD'=>$password];$this->attest($a);$this->run([...$c,'stop',$s['web'],$s['worker'],$s['scheduler']]);$this->attest($a);$db=$a->value('database');$this->run([...$c,'exec','-T','-e','MYSQL_PWD',$s['database'],'mariadb','-u',$a->value('database_user'),'-e','DROP DATABASE IF EXISTS `'.$db.'`; CREATE DATABASE `'.$db.'`;'],'',$env);$this->attest($a);$this->run([...$c,'exec','-T','-e','MYSQL_PWD',$s['database'],'mariadb','-u',$a->value('database_user'),$db],$p['database.sql'],$env);foreach(['artifacts'=>'artifacts.tar','sessions'=>'sessions.json']as$r=>$member){$this->attest($a);$this->volume($a,$r,$p[$member]);}$this->attest($a);$this->run([...$c,'up','-d','--no-deps',$s['web'],$s['worker'],$s['scheduler']]);$e=$this->evidence($a,$c,$s,$env);$this->attest($a);return['outcome'=>'RESTORE_VERIFIED','evidence'=>$e];}catch(\Throwable){return['outcome'=>'OUTCOME_UNKNOWN','evidence'=>[]];}}
 private function attest(StandRestoreAuthorization$a):void{if(!$this->matches($a,$this->observe($a)))throw new \RuntimeException();}
 private function observe(StandRestoreAuthorization$a):array{$s=$a->value('services');$c=$this->compose($a);$id=trim($this->run([...$c,'ps','-q',$s['database']]));$o=['database_container_id'=>$id,'project_id'=>trim($this->run(['docker','inspect','--format','{{index .Config.Labels "com.docker.compose.project"}}',$id])),'network_id'=>trim($this->run(['docker','inspect','--format','{{range $k,$v := .NetworkSettings.Networks}}{{$v.NetworkID}}{{end}}',$id]))];foreach($a->value('volumes')as$r=>$v)$o['volume:'.$r]=hash('sha256',$this->run(['docker','volume','inspect',$v['name']]));return$o;}
 private function matches(StandRestoreAuthorization$a,array$o):bool{$w=$a->value('observed');foreach(['project_id','network_id','database_container_id']as$k)if($w[$k]!==($o[$k]??null))return false;foreach($a->value('volumes')as$r=>$v)if($v['observed_id']!==($o['volume:'.$r]??null))return false;return true;}
 private function volume(StandRestoreAuthorization$a,string$r,string$bytes):void{$volume=$a->value('volumes')[$r]['name'];$root='/state/fmonitor2/'.$r;$op=$a->value('operation_id');$stage='/state/.restore-'.$r.'-'.$op;$old='/state/.previous-'.$r.'-'.$op;$kind=$r==='artifacts'?'artifact':'session';$expected=$a->value('expected')[$kind];$script='set -eu; rm -rf "$STAGE" "$OLD"; mkdir -m 700 "$STAGE"; cat > "$STAGE/archive.tar"; for P in $(tar -tf "$STAGE/archive.tar"); do case "$P" in /*|../*|*/../*) exit 1;; esac; done; tar -xpf "$STAGE/archive.tar" -C "$STAGE"; rm "$STAGE/archive.tar"; test -z "$(find "$STAGE" -type l -print -quit)"; test "$(sha256sum "$STAGE/$EXPECTED_PATH" | cut -d " " -f 1)" = "$EXPECTED_SHA"; if test -n "$EXPECTED_MODE"; then test "$(stat -c %a "$STAGE/$EXPECTED_PATH")" = "$EXPECTED_MODE"; fi; find "$STAGE" -type f -exec sync -f {} \;; find "$STAGE" -depth -type d -exec sync -f {} \;; mkdir -p "$(dirname "$ROOT")"; if test -e "$ROOT"; then mv "$ROOT" "$OLD"; fi; mv "$STAGE" "$ROOT"; sync -f "$(dirname "$ROOT")"; rm -rf "$OLD"';$this->run(['docker','run','--rm','--network','none','-e','ROOT='.$root,'-e','STAGE='.$stage,'-e','OLD='.$old,'-e','EXPECTED_PATH='.$expected['path'],'-e','EXPECTED_SHA='.$expected['sha256'],'-e','EXPECTED_MODE='.($expected['mode']??''),'--mount','type=volume,source='.$volume.',target=/state',$a->value('image'),'sh','-c',$script],$bytes);}
 private function evidence(StandRestoreAuthorization$a,array$c,array$s,array$env):array{$db=$a->value('database');$x=$a->value('expected');$q=fn(string$sql)=>trim($this->run([...$c,'exec','-T','-e','MYSQL_PWD',$s['database'],'mariadb','-N','-B','-u',$a->value('database_user'),$db,'-e',$sql],'',$env));$schema=$q("SELECT CONCAT(TABLE_NAME,'|',ENGINE,'|',COALESCE(AUTO_INCREMENT,0)) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME");$jobs=$q("SELECT state,deduplication_key FROM fm2_jobs WHERE deduplication_key='restore-rehearsal-job' ORDER BY id")===$x['jobs_rows']&&$q("SELECT state FROM fm2_outbox WHERE idempotency_key='restore-rehearsal-outbox' ORDER BY id")===$x['outbox_rows']&&$q("SELECT lease_owner FROM fm2_jobs WHERE deduplication_key='restore-rehearsal-job' ORDER BY id")===$x['job_lease_rows']&&$q("SELECT state FROM fm2_job_recovery ORDER BY id")===$x['recovery_rows'];$e=['database'=>$q("SELECT id,fact FROM fm2_restore_rehearsal_probe WHERE id=7 ORDER BY id")===$x['sentinel_rows'],'schema'=>hash('sha256',$schema."\n")===$x['schema_sha256'],'history'=>$q('SELECT id,fact FROM fm2_restore_rehearsal_probe ORDER BY id')===$x['history_rows'],'jobs'=>$jobs];$next=(int)$x['next_id'];$probe=$q("START TRANSACTION; INSERT INTO fm2_restore_rehearsal_probe(fact) VALUES ('controlled-next-id'); SELECT LAST_INSERT_ID(); ROLLBACK; ALTER TABLE fm2_restore_rehearsal_probe AUTO_INCREMENT=".$next);$e['auto_increment']=(int)explode("\n",$probe)[0]===$next;foreach(['live','ready']as$n){$this->run(['curl','--fail','--silent','--show-error','--max-time','30',$a->value('health')[$n]]);$e[$n]=true;}foreach(['artifact'=>'artifacts','session'=>'sessions']as$kind=>$r){$expected=$x[$kind];$out=$this->run(['docker','run','--rm','--network','none','-e','P=/state/fmonitor2/'.$r.'/'.$expected['path'],'--mount','type=volume,source='.$a->value('volumes')[$r]['name'].',target=/state,readonly',$a->value('image'),'sh','-c','test -f "$P"; sha256sum "$P"; stat -c %a "$P"']);$lines=explode("\n",trim($out));$e[$r]=strtok($lines[0]??'',' ')===$expected['sha256']&&($kind==='session'||(int)($lines[1]??-1)===(int)$expected['mode']);}$e['golden']=true;foreach($a->value('golden')as$g){$bytes=$this->run(['curl','--fail','--silent','--show-error','--max-time','30',$g['url']]);if(hash('sha256',$bytes)!==$g['sha256'])$e['golden']=false;}return$e;}
 private function compose(StandRestoreAuthorization$a):array{return['docker','compose','--project-name',$a->value('project'),'--file',$a->value('compose_file')];}
 private function run(array$argv,string$stdin='',array$env=[]):string{$pipes=[];$p=proc_open($argv,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,array_merge($_ENV,$env));if(!is_resource($p))throw new \RuntimeException();fwrite($pipes[0],$stdin);fclose($pipes[0]);$out=stream_get_contents($pipes[1]);fclose($pipes[1]);stream_get_contents($pipes[2]);fclose($pipes[2]);if(proc_close($p)!==0)throw new \RuntimeException();return$out;}
}
